-- Writes modules/engine_handles.lua and types/SpringHandles.lua from the recoil-lua-library listings. Run from the
-- repo root after a submodule bump, then stylua on types/SpringHandles.lua (it wraps the longer signatures):
--   luajit tools/engine_handles/generate.lua && stylua types/SpringHandles.lua
-- spec/modules/engine_handles_spec.lua fails until the generated files match the listings again.
package.path = "./?.lua;" .. package.path
local Derive = require("tools/engine_handles/derive")

local syncedOnly, unsyncedOnly = Derive.Sides()
assert(syncedOnly and unsyncedOnly, "recoil-lua-library listings not checked out")

---@param names string[]
---@return string
local function block(names)
	local lines = {}
	for _, name in ipairs(names) do
		lines[#lines + 1] = string.format('\t\t"%s",', name)
	end
	return table.concat(lines, "\n")
end

local out = assert(io.open("modules/engine_handles.lua", "w"))
out:write(
	"-- GENERATED by tools/engine_handles/generate.lua from recoil-lua-library/library/generated/rts/Lua/; do not edit.\n"
		.. "-- The Spring functions the engine offers in one Lua handle only. modules/module_env.lua refuses them from a file\n"
		.. "-- declared for the other handle, or for any; spec/modules/engine_handles_spec.lua fails when this drifts.\n"
		.. "---@class EngineHandles\n"
		.. "---@field syncedOnly string[]\n"
		.. "---@field unsyncedOnly string[]\n"
		.. "return {\n\tsyncedOnly = {\n"
		.. block(Derive.Sorted(syncedOnly))
		.. "\n\t},\n\tunsyncedOnly = {\n"
		.. block(Derive.Sorted(unsyncedOnly))
		.. "\n\t},\n}\n"
)
out:close()
-- the tree keeps CRLF, so the checked-in file is what the working copy holds
local types = assert(io.open("types/SpringHandles.lua", "wb"))
types:write((assert(Derive.RenderTypes(syncedOnly, unsyncedOnly)):gsub("\n", "\r\n")))
types:close()
print(
	string.format(
		"modules/engine_handles.lua + types/SpringHandles.lua: %d synced-only, %d unsynced-only",
		#Derive.Sorted(syncedOnly),
		#Derive.Sorted(unsyncedOnly)
	)
)
